const root=path.resolve(__dirname,'..'),out=path.resolve(process.env.FOOD_DYNAMIC_OUT_DIR||path.join(__dirname,'food-dynamic-v10'),'seam');fs.mkdirSync(out,{recursive:true});
const core=fs.readFileSync(path.join(root,'dist/core.js'),'utf8'),source=fs.readFileSync(path.join(root,'dist/scenes/toaster.js'),'utf8');
const marker='if(!zone||original.every';assert.ok(source.includes(marker),'expected original-edge paint guard');
// Force the new paint helper to outline its closed cut polygon: exactly reproduces the rejected seam.
const bug=source.replace(marker,'if(true||!zone||original.every');
function rig(src,track=false){const ctx=vm.createContext({window:{},console,addEventListener(){},Math,Number,__paint:[],__edges:[]});vm.runInContext(core,ctx);if(track)src=src.replace('const paint=(original,points,color,w)=>{','const paint=(original,points,color,w)=>{if(zone&&w)globalThis.__paint.push({original,points,zone});').replace('edges+=pd([a,b],false);','globalThis.__edges.push({original,a,b});edges+=pd([a,b],false);');vm.runInContext(src,ctx);const cfg=ctx.window.SCENES.toaster();cfg.state.pal='mint';return {ctx,cfg,render(k,yaw=135,pitch=6,phase='loading'){Object.assign(cfg.state,{phase,slices:2,loadT:phase==='loading'?k:1,takeT:phase==='taking'?1-k:0,progress:phase==='taking'?1:0});vm.runInContext(`setCam(${yaw},${pitch});setLight(105);INK_K=.5;`,ctx);ctx.__paint=[];ctx.__edges=[];return cfg.scene(cfg.state,vm.runInContext('PALS.mint',ctx));}};}
const fixed=rig(source,true),old=rig(bug),eps=1e-8;let renders=0,cutFaces=0,originalSegments=0,oldArtificialEdges=0;
function onSegment(p,a,b){const d=b.map((v,i)=>v-a[i]),len=d.reduce((s,v)=>s+v*v,0),t=len?p.reduce((s,v,i)=>s+(v-a[i])*d[i],0)/len:0;return t>=-eps&&t<=1+eps&&Math.hypot(...p.map((v,i)=>v-a[i]-t*d[i]))<eps;}
for(const phase of ['loading','taking'])for(const yaw of [135,180,225])for(const pitch of [6,35.264,78])for(let i=120;i<=190;i++){fixed.render(i/1000,yaw,pitch,phase);renders++;for(const {original,points,zone}of fixed.ctx.__paint){if(original.every(p=>(p[2]-46.7)*zone>=0))continue;cutFaces++;for(let j=0;j<points.length;j++){const a=points[j],b=points[(j+1)%points.length];if(Math.abs(a[2]-46.7)<eps&&Math.abs(b[2]-46.7)<eps&&!original.some((p,n)=>onSegment(a,p,original[(n+1)%original.length])&&onSegment(b,p,original[(n+1)%original.length])))oldArtificialEdges++;}}
for(const {original,a,b}of fixed.ctx.__edges){originalSegments++;assert.ok(original.some((p,n)=>onSegment(a,p,original[(n+1)%original.length])&&onSegment(b,p,original[(n+1)%original.length])),'all rendered ink is part of an original physical edge');}}
