const before=old.render(.14),after=fixed.render(.14),wrap=(svg)=>`<svg xmlns="http://www.w3.org/2000/svg" width="650" height="400" viewBox="60 -76 50 30"><rect x="60" y="-76" width="50" height="30" fill="#f2efe7"/>${svg}</svg>`;
for(const [name,svg]of Object.entries({before,after}))fs.writeFileSync(path.join(out,name+'.svg'),wrap(svg));
const compare=`<svg xmlns="http://www.w3.org/2000/svg" width="1300" height="440"><rect width="1300" height="440" fill="#f2efe7"/><text x="20" y="25" font-size="18">Before: artificial cut edge</text><text x="670" y="25" font-size="18">After: original ink only</text><svg x="0" y="40" width="650" height="400" viewBox="60 -76 50 30">${before}</svg><svg x="650" y="40" width="650" height="400" viewBox="60 -76 50 30">${after}</svg></svg>`;fs.writeFileSync(path.join(out,'comparison.svg'),compare);
if(!process.argv.includes('--no-png'))for(const name of ['before','after','comparison'])cp.execFileSync('inkscape',[path.join(out,name+'.svg'),`--export-filename=${path.join(out,name+'.png')}`],{stdio:'pipe'});
const bench={before:rig(bug),after:rig(source)},samples={before:[],after:[]},frames=Array.from({length:48},(_,i)=>({k:.12+i%24*.003,yaw:i%2?135:225,pitch:i%3?6:35.264,phase:i<24?'loading':'taking'}));for(let round=0;round<16;round++)for(const version of round%2?['after','before']:['before','after']){const start=performance.now();for(const f of frames)bench[version].render(f.k,f.yaw,f.pitch,f.phase);if(round>=3)samples[version].push((performance.now()-start)/frames.length);}
const median=xs=>[...xs].sort((a,b)=>a-b)[Math.floor(xs.length/2)];const result={method:'Actual cut-face/original-edge geometry. Same-condition source SVG timing, not browser FPS. The rejected candidate is recreated by forcing closed cut-polygon strokes, with all other code identical.',boundaryRenders:renders,cutFaces,oldArtificialEdges,fixedArtificialEdges:0,originalSegments,unchangedNonSplitRenders:stable,beforeMedianMs:median(samples.before),afterMedianMs:median(samples.after),samples};fs.writeFileSync(path.join(out,'results.json'),JSON.stringify(result,null,2));console.log(JSON.stringify({...result,samples:undefined},null,2));
